package co.edu.cinematch.core.model;
import java.time.LocalDate; import java.util.*;
public class Reserva implements Identifiable { private String id,clienteId,funcionId; private LocalDate fechaReserva; private EstadoReserva estado=EstadoReserva.PENDIENTE; private double total; private List<String> asientoIds=new ArrayList<>(); public Reserva(){} public Reserva(String clienteId,String funcionId,LocalDate fecha){this.clienteId=clienteId;this.funcionId=funcionId;fechaReserva=fecha;} public String getId(){return id;}public void setId(String v){id=v;}public String getClienteId(){return clienteId;}public void setClienteId(String v){clienteId=v;}public String getFuncionId(){return funcionId;}public void setFuncionId(String v){funcionId=v;}public LocalDate getFechaReserva(){return fechaReserva;}public void setFechaReserva(LocalDate v){fechaReserva=v;}public EstadoReserva getEstado(){return estado;}public void setEstado(EstadoReserva v){estado=v;}public double getTotal(){return total;}public void setTotal(double v){total=v;}public List<String> getAsientoIds(){return asientoIds;}public void setAsientoIds(List<String> v){asientoIds=v==null?new ArrayList<>():new ArrayList<>(v);} }
